// Get the 4 vertices of the cell in 3D space
std::array<Weighted_point, 4> pts;
for (int i = 0; i < 4; ++i) {
    pts[i] = c->vertex(i)->point();
}

// Lift points to 4D space (x,y,z,w) where w = (x²+y²+z² - weight)/2
std::array<LiftedPoint, 4> lifted_pts;
for (int i = 0; i < 4; ++i) {
    double x = pts[i].x();
    double y = pts[i].y();
    double z = pts[i].z();
    double w = (x*x + y*y + z*z - pts[i].weight()) / 2.0;
    lifted_pts[i] = lifted_point(x, y, z, w);
}

// Create hyperplane through the 4 lifted points
HyperPlane hp(lifted_pts[0], lifted_pts[1], lifted_pts[2], lifted_pts[3]);

// The hyperplane equation is: a*x + b*y + c*z + d*w + e = 0
// The normal vector is (a,b,c,d), and we want the velocity = (a,b,c)/d
// But we need to handle the case where d=0 (infinite velocity)
double a = hp.a(0);
double b = hp.a(1);
double c = hp.a(2);
double d = hp.a(3);
double e = hp.e();

// The velocity is the spatial part of the normal vector divided by the negative
// of the w-component (time component) of the normal vector
if (std::abs(d) < 1e-10) {
    // Infinite velocity case - return zero or some large value?
    // Based on context, returning zero might be appropriate
    return Vector(0.0, 0.0, 0.0);
} else {
    return Vector(-a/d, -b/d, -c/d);
}

